using System;
using System.Collections.Generic;
using GrimDynasty.ReverseClient.Actions;

// The existing saved-resource request producer is invoked as a public method;
// its old executable Main and old suites are not run. Only the new waypoint
// adapter/cold vector/borrow/trim continuation is reported as new coverage.
public static class MainmenuCrowdPathPipeline {
 static void Require(bool value,string why){if(!value)throw new InvalidOperationException(why);}
 static NavigationCrowdPointAddress Address(object value){return (NavigationCrowdPointAddress)value;}
 static int Count(NavigationCrowdWaypointVector v){return checked((int)(Address(v.End08.Read(0)).PointIndex-Address(v.Begin00.Read(0)).PointIndex));}
 static uint[] Bits(NavigationPoint3 p){return new[]{NavigationCoreContracts.ToBits(p.X.Read(0)),NavigationCoreContracts.ToBits(p.Y.Read(0)),NavigationCoreContracts.ToBits(p.Z.Read(0))};}
 static uint[] PointBits(NavigationPointBuffer b,int n){return new[]{NavigationCoreContracts.ToBits(b.At(n*3,0).Read(0)),NavigationCoreContracts.ToBits(b.At(n*3+1,0).Read(0)),NavigationCoreContracts.ToBits(b.At(n*3+2,0).Read(0))};}
 static bool SameBits(uint[] a,uint[] b){return a[0]==b[0]&&a[1]==b[1]&&a[2]==b[2];}
 static string Hex(uint[] point){return point[0].ToString("X8")+"/"+point[1].ToString("X8")+"/"+point[2].ToString("X8");}
 public static int Main(string[] args){try{
  Require(args.Length==2&&args[0]=="--explicit-default-domain"&&args[1]=="--own-disk-ce70-noop","Explicit own cold domain and disk-leaf hook adapter must both be selected");
  var context=MainmenuCrowdRequestPipeline.BuildExplicitRequestContext();var request=context.Request;var positionBefore=Bits(context.Agent.Position48);var references=request.RefVector20;var referenceBegin=references.Begin00.Read(0);var referenceEnd=references.End08.Read(0);var referenceCapacity=references.Capacity10.Read(0);var referenceBits=new uint[context.CorridorCount];for(int n=0;n<referenceBits.Length;n++)referenceBits[n]=referenceBegin.Buffer.At(referenceBegin.Index+n,0).Read(0);
  Require(context.TileCount==9&&context.TileCrossings>0,"Actual saved-resource cross-tile request prerequisite");Require(Object.ReferenceEquals(context.Query,context.Adapter.Query10.Read(0))&&Object.ReferenceEquals(context.Mesh.Mesh,context.Query.Mesh0.Read(0)),"Shared producer query/mesh required");
  var header=request.WaypointVector38;Require(header.Begin00.Read(0)==null&&header.End08.Read(0)==null&&header.Capacity10.Read(0)==null,"Cold waypoint triple must be actual constructor state, not preallocated output");var vector=new NavigationCrowdWaypointVector(header);var b=new NavigationCrowdPathBoundaries(context.Mesh);b.UseObservedPathConstants();b.UseObservedStraightPathConstants();b.UseObservedEqualityConstant();b.DisableTrimAssert422B93.Write(0);b.DisableSecondAssert422B92.Write(0);b.DisablePopAssert422B94.Write(0);b.DisableAllAssert42144A.Write(0);b.UseObservedDiskNoOp00CE70OwnAdapter();
  Require(NavigationCrowdPathContracts.StraightPath030900(context.Adapter,request.From04,request.To10,references,vector,b,new Invocation())==1,"Actual waypoint adapter returned failure");int count=Count(vector);var storage=Address(vector.Begin00.Read(0)).Buffer;Require(count>=2&&count<=4,"Actual adapter must produce a nontrivial route within its fixed four points");Require(Object.ReferenceEquals(header.Begin00,vector.Begin00)&&Object.ReferenceEquals(header.End08,vector.End08)&&Object.ReferenceEquals(header.Capacity10,vector.Capacity10),"Typed view must share original request header cells");Require(Object.ReferenceEquals(storage,Address(vector.End08.Read(0)).Buffer)&&Object.ReferenceEquals(storage,Address(vector.Capacity10.Read(0)).Buffer),"All published addresses must share real new allocation");
  var points=new List<uint[]>();var text=new List<string>();for(int n=0;n<count;n++){var point=PointBits(storage,n);points.Add(point);text.Add(Hex(point));}Require(SameBits(points[0],Bits(request.From04))&&SameBits(points[count-1],Bits(request.To10)),"Nonfailure alone is insufficient: this sample requires both requested endpoints");
  var borrowed=NavigationCrowdPathContracts.Second25C080(request,b,new Invocation());Require(Object.ReferenceEquals(storage,borrowed.Buffer)&&borrowed.PointIndex==1,"Second waypoint must borrow actual produced storage");Require(Object.ReferenceEquals(storage.At(3,0),borrowed.Cell(0,0)),"Borrowed point must expose actual shared scalar cell");
  NavigationCrowdPathContracts.TrimWaypoints25BA90(request,request.From04,b,new Invocation());int retained=Count(vector),removed=count-retained;Require(removed>=1&&retained>=1,"Actual start prefix should be removed while a later route point remains");Require(Object.ReferenceEquals(storage,Address(vector.Begin00.Read(0)).Buffer),"Trim must keep allocation identity");for(int n=0;n<retained;n++)Require(SameBits(points[n+removed],PointBits(storage,n)),"Trim must preserve actual suffix in order");Require(Object.ReferenceEquals(storage.At(3,0),borrowed.Cell(0,0)),"Borrowed address remains same cell after in-place trim");
  Require(Object.ReferenceEquals(referenceBegin,references.Begin00.Read(0))&&Object.ReferenceEquals(referenceEnd,references.End08.Read(0))&&Object.ReferenceEquals(referenceCapacity,references.Capacity10.Read(0)),"Waypoint continuation must not replace corridor addresses");for(int n=0;n<referenceBits.Length;n++)Require(referenceBits[n]==referenceBegin.Buffer.At(referenceBegin.Index+n,0).Read(0),"Original corridor payload retained");Require(Object.ReferenceEquals(request,context.Agent.RequestE8)&&SameBits(positionBefore,Bits(context.Agent.Position48)),"Request identity retained and agent position remains unchanged");Require(b.OwnOutstandingEnters==0,"Own adapter lock released");
  Console.WriteLine("CROWD PATH CONFIG reused explicit saved-resource request context; native null waypoint triple; actual stride12 growth; explicitly selected own disk-CE70 no-op adapter; loaded hook behavior and native allocator/EH unobserved");Console.WriteLine("CROWD PATH tiles="+context.TileCount+" corridor="+context.CorridorCount+" tileCrossings="+context.TileCrossings+" waypoints="+count+" removedPrefix="+removed+" remaining="+retained+" coordinatesBinary32="+String.Join(",",text.ToArray()));Console.WriteLine("PASS actual saved tiles=9, same request corridor-to-waypoint cold growth and borrowed/in-place trim; position unchanged; no loaded Player, character movement or R1 game acceptance");return 0;
 }catch(Exception e){Console.Error.WriteLine("FAIL "+e);return 1;}}
}
